UPDATE businesses SET description = 'Garment Care SA is a textile care chemical manufacturer and consultant based in Icon Industrial Park, Sunderland Ridge, Centurion, supplying laundry detergents, laundry chemicals, dry-cleaning and spotting products, and finishing supplies to the dry-cleaning and laundry trade. Its dry-cleaning range includes perchloroethylene stabilised to dry-cleaning grade and imported from Europe, alongside auxiliaries such as lint roller refills and bio power laundry detergent sold in 25 kilogram quantities.

The company also stocks finishing and packaging accessories including brown paper, pvc-coated hangers supplied 500 to a box, iron board covers, suit covers, sanitary bin bags and plastic bags and rolls in several sizes. Deliveries run daily within Gauteng, with a minimum order of R2,000, and once a month to Limpopo, KwaZulu-Natal, the Free State, North West, Mpumalanga and the Northern Cape. It suits dry cleaners and laundries across South Africa and neighbouring countries that need chemicals, detergents and packaging supplies from a specialist manufacturer, and the business is on Kwanbi Crescent in Sunderland Ridge.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.garmentcare.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'garment-care-sa-sunderland-ridge' AND description = 'Garment Care SA is a dry-cleaning and laundry detergent manufacturer based in Icon Industrial Park, Sunderland Ridge, producing professional cleaning solutions, detergents and accessories for the dry-cleaning and laundry trade, and supplying customers across South Africa and neighbouring countries.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- gecko-ridge-wedding-venue-donkerhoek (researched)
UPDATE businesses SET description = 'Gecko Ridge Wedding Venue is a wedding and function venue on the banks of the Pienaars River near Mooiplaas, offering chapels and banquet halls that accommodate between 20 and 600 guests. Beyond weddings, the venue hosts conferences, team building, product launches, brand awareness events, year-end functions, matric farewells, parties and birthday celebrations, with on-site accommodation available for guests who want to stay over.

The venue also runs food-tasting events open to the public, giving couples the chance to meet and discuss requirements with the venue''s industry suppliers while sampling the food on offer, which reviewers describe as being on another level. Past clients have praised the team for going out of their way to help and accommodate any request, alongside the venue''s beautiful setting and attentive service. It suits couples and event organisers looking for a riverside venue that can scale from an intimate gathering to a large banquet, and the venue is on Gecko Ridge Road in Mooiplaas.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://geckoridgevenue.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'gecko-ridge-wedding-venue-donkerhoek' AND description = 'Gecko Ridge Wedding Venue is a wedding and function venue on the banks of the Pienaars River near Mooiplaas, with chapels and banquet halls accommodating between 20 and 600 guests for weddings, conferences and other functions, plus on-site accommodation.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
