-- gigi-s-furniture-removals-gauteng-bergtuin (researched)
UPDATE businesses SET description = 'Gigi''s Furniture Removals has been moving homes and offices in Pretoria, Johannesburg and Cape Town for 60 years, servicing the entire Gauteng and Western Cape areas from its branch in Jan Niemand Park, Pretoria. The company offers private storage and packing services, using closed-body vehicles that protect furniture and belongings from the weather during transit.

Every move includes R150,000 of goods-in-transit insurance as standard, and the company says it will never cut corners or apply hidden costs, aiming to keep removals affordable while maintaining a professional standard of service. Client privacy is treated seriously, with new addresses, phone numbers, furniture lists and removal dates kept confidential and never disclosed to a third party without a valid court order. It suits households and offices moving within Gauteng, to Cape Town, or further afield who want an experienced, insured removals company, and the Pretoria branch is on Brander Street in Jan Niemand Park.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.gigisremovals.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'gigi-s-furniture-removals-gauteng-bergtuin' AND description = 'Gigi''s Furniture Removals has moved homes and offices across Gauteng and the Western Cape since 1966, offering private storage and packing services, closed-body vehicles to protect goods from the weather, and R150,000 goods-in-transit insurance included on every move.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
